insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'promptpilot', 'en', '{"title":"PromptPilot","summary":"A clearer workflow for prompts, with account settings, saved history and an interchangeable AI provider.","category":"Full-stack · AI tooling","role":"Built independently, from interface to backend","status":"Prototype · Preparing for beta","stack":["Next.js","TypeScript","Supabase","OpenAI"],"repository":"https://github.com/sardorcodev/PromptPilot","image":"/images/projects/promptpilot.webp","imageAlt":"PromptPilot running locally in its development configuration.","body":"## The problem\n\nPrompt workflows become harder to manage when instructions, preferences and earlier results are scattered across different places.\n\n## What I built\n\nI built a Next.js application that brings prompt tools, account preferences and history into one workflow. Supabase supports authentication and persistence, while the AI layer can use a mock provider or OpenAI.\n\n## My contribution\n\n- Designed and implemented the application end to end.\n\n- Built the interface and the prompt and developer workflows.\n\n- Connected authentication, settings and history to Supabase.\n\n- Implemented provider selection, fallback behavior and server-side request guards.\n\n## Behind the decisions\n\n### Keep the AI provider replaceable\n\nThe provider factory separates the workflow from the service that generates the response. Mock mode also supports development without a live API.\n\n### Make persistence a user choice\n\nAccount preferences control history saving, while row-level security policies define data ownership.\n\n## What I learned\n\nConnecting an interface to authentication, persistence and an external AI service means thinking about failure states and account boundaries throughout the application.\n\n## What comes next\n\n- Complete the closed-beta checklist and verify the core flows in a configured deployment.\n\n- Validate account isolation, provider fallback and release rollback.\n\n- Gather feedback before treating the application as a released product.","order":0}'::jsonb, '{"title":"PromptPilot","summary":"A clearer workflow for prompts, with account settings, saved history and an interchangeable AI provider.","category":"Full-stack · AI tooling","role":"Built independently, from interface to backend","status":"Prototype · Preparing for beta","stack":["Next.js","TypeScript","Supabase","OpenAI"],"repository":"https://github.com/sardorcodev/PromptPilot","image":"/images/projects/promptpilot.webp","imageAlt":"PromptPilot running locally in its development configuration.","body":"## The problem\n\nPrompt workflows become harder to manage when instructions, preferences and earlier results are scattered across different places.\n\n## What I built\n\nI built a Next.js application that brings prompt tools, account preferences and history into one workflow. Supabase supports authentication and persistence, while the AI layer can use a mock provider or OpenAI.\n\n## My contribution\n\n- Designed and implemented the application end to end.\n\n- Built the interface and the prompt and developer workflows.\n\n- Connected authentication, settings and history to Supabase.\n\n- Implemented provider selection, fallback behavior and server-side request guards.\n\n## Behind the decisions\n\n### Keep the AI provider replaceable\n\nThe provider factory separates the workflow from the service that generates the response. Mock mode also supports development without a live API.\n\n### Make persistence a user choice\n\nAccount preferences control history saving, while row-level security policies define data ownership.\n\n## What I learned\n\nConnecting an interface to authentication, persistence and an external AI service means thinking about failure states and account boundaries throughout the application.\n\n## What comes next\n\n- Complete the closed-beta checklist and verify the core flows in a configured deployment.\n\n- Validate account isolation, provider fallback and release rollback.\n\n- Gather feedback before treating the application as a released product.","order":0}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'smart-agro-ai', 'en', '{"title":"Smart Agro AI","summary":"An agriculture dashboard connecting a React interface with a Python API and the team’s crop recommendation model.","category":"Full-stack · Team MVP","role":"Frontend and backend; ML developed separately","status":"MVP · Demo","stack":["React","FastAPI","Python","SQLite"],"repository":"https://github.com/sardorcodev/smart-agroAI","image":"/images/projects/smart-agro-ai.webp","imageAlt":"The Smart Agro AI MVP interface. Some dashboard modules are demo features.","body":"## The problem\n\nAn agriculture decision-support prototype needs to bring inputs, weather context and crop recommendations into one understandable workflow.\n\n## What I built\n\nI built the application outside its ML component, including the React frontend and FastAPI backend. The MVP connects input forms, analysis results and weather context, while the team’s model supplies crop recommendations.\n\n## My contribution\n\n- Built the frontend and backend parts of the application.\n\n- Implemented the interface for inputs and analysis results.\n\n- Worked on the API and data flow that support the dashboard.\n\n- Contributed to GREEN OPS as part of the hackathon team.\n\n## Behind the decisions\n\n### Show the recommendation in context\n\nA dashboard connects the inputs and weather context with the output, helping someone understand the workflow rather than only seeing a prediction.\n\n### Be clear about demo behavior\n\nThe backend distinguishes model inference from a simulation fallback. The application remains an MVP, with model validation and dataset provenance still limited.\n\n## What I learned\n\nBuilding around a team’s ML component helped me understand the boundaries between a model, an API and the interface that presents its output.\n\n## What comes next\n\n- Improve the end-to-end analysis experience and its error states.\n\n- Continue strengthening the interface and backend.\n\n- Work with the ML contributor on dataset provenance and validation before considering real-world use.","order":1}'::jsonb, '{"title":"Smart Agro AI","summary":"An agriculture dashboard connecting a React interface with a Python API and the team’s crop recommendation model.","category":"Full-stack · Team MVP","role":"Frontend and backend; ML developed separately","status":"MVP · Demo","stack":["React","FastAPI","Python","SQLite"],"repository":"https://github.com/sardorcodev/smart-agroAI","image":"/images/projects/smart-agro-ai.webp","imageAlt":"The Smart Agro AI MVP interface. Some dashboard modules are demo features.","body":"## The problem\n\nAn agriculture decision-support prototype needs to bring inputs, weather context and crop recommendations into one understandable workflow.\n\n## What I built\n\nI built the application outside its ML component, including the React frontend and FastAPI backend. The MVP connects input forms, analysis results and weather context, while the team’s model supplies crop recommendations.\n\n## My contribution\n\n- Built the frontend and backend parts of the application.\n\n- Implemented the interface for inputs and analysis results.\n\n- Worked on the API and data flow that support the dashboard.\n\n- Contributed to GREEN OPS as part of the hackathon team.\n\n## Behind the decisions\n\n### Show the recommendation in context\n\nA dashboard connects the inputs and weather context with the output, helping someone understand the workflow rather than only seeing a prediction.\n\n### Be clear about demo behavior\n\nThe backend distinguishes model inference from a simulation fallback. The application remains an MVP, with model validation and dataset provenance still limited.\n\n## What I learned\n\nBuilding around a team’s ML component helped me understand the boundaries between a model, an API and the interface that presents its output.\n\n## What comes next\n\n- Improve the end-to-end analysis experience and its error states.\n\n- Continue strengthening the interface and backend.\n\n- Work with the ML contributor on dataset provenance and validation before considering real-world use.","order":1}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'propaint', 'en', '{"title":"ProPaint","summary":"A browser painting editor with custom Canvas tools, undo and redo, color controls and PNG export.","category":"Frontend · Creative tool","role":"Built independently, from start to finish","status":"Prototype · Stabilizing","stack":["React","JavaScript","Canvas","Redux Toolkit"],"repository":"https://github.com/sardorcodev/paint-web","image":"/images/projects/propaint.webp","imageAlt":"ProPaint running locally, with its Canvas editor and drawing controls.","body":"## The problem\n\nA drawing editor needs the tools, canvas state and history to stay in sync while the user moves quickly between actions.\n\n## What I built\n\nI built a React application around a custom Canvas editor. The existing prototype supports drawing, simple shapes, color selection, undo and redo, and exporting a PNG.\n\n## My contribution\n\n- Built the application independently.\n\n- Implemented the custom Canvas editor and drawing tools.\n\n- Connected editor controls and state through React and Redux Toolkit.\n\n- Implemented history management and image export.\n\n## Behind the decisions\n\n### Separate the editor responsibilities\n\nThe editor has controller, renderer, history and tool modules. This makes drawing behavior easier to evolve without putting all of the logic into a React component.\n\n### Stabilize the core interaction first\n\nThe current focus is the drawing and history workflow. Save/load, a layers interface and zoom/pan remain future work.\n\n## What I learned\n\nInteractive Canvas work brings rendering, input handling and state management together. Undo and redo also require a clear definition of an editor action.\n\n## What comes next\n\n- Stabilize the existing editor and validate history behavior.\n\n- Improve documentation and align it with the test setup.\n\n- Explore save/load and navigation around the canvas after the foundation is stable.","order":2}'::jsonb, '{"title":"ProPaint","summary":"A browser painting editor with custom Canvas tools, undo and redo, color controls and PNG export.","category":"Frontend · Creative tool","role":"Built independently, from start to finish","status":"Prototype · Stabilizing","stack":["React","JavaScript","Canvas","Redux Toolkit"],"repository":"https://github.com/sardorcodev/paint-web","image":"/images/projects/propaint.webp","imageAlt":"ProPaint running locally, with its Canvas editor and drawing controls.","body":"## The problem\n\nA drawing editor needs the tools, canvas state and history to stay in sync while the user moves quickly between actions.\n\n## What I built\n\nI built a React application around a custom Canvas editor. The existing prototype supports drawing, simple shapes, color selection, undo and redo, and exporting a PNG.\n\n## My contribution\n\n- Built the application independently.\n\n- Implemented the custom Canvas editor and drawing tools.\n\n- Connected editor controls and state through React and Redux Toolkit.\n\n- Implemented history management and image export.\n\n## Behind the decisions\n\n### Separate the editor responsibilities\n\nThe editor has controller, renderer, history and tool modules. This makes drawing behavior easier to evolve without putting all of the logic into a React component.\n\n### Stabilize the core interaction first\n\nThe current focus is the drawing and history workflow. Save/load, a layers interface and zoom/pan remain future work.\n\n## What I learned\n\nInteractive Canvas work brings rendering, input handling and state management together. Undo and redo also require a clear definition of an editor action.\n\n## What comes next\n\n- Stabilize the existing editor and validate history behavior.\n\n- Improve documentation and align it with the test setup.\n\n- Explore save/load and navigation around the canvas after the foundation is stable.","order":2}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
