insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'promptpilot', 'uz', '{"title":"PromptPilot","summary":"Promptlar bilan ishlashni tartibga soluvchi ilova: akkaunt sozlamalari, saqlangan tarix va almashtiriladigan AI provayder.","category":"Full-stack · AI vositasi","role":"Interfeysdan backendgacha mustaqil yaratdim","status":"Prototip · Beta sinoviga tayyorgarlik","stack":["Next.js","TypeScript","Supabase","OpenAI"],"repository":"https://github.com/sardorcodev/PromptPilot","image":"/images/projects/promptpilot.webp","imageAlt":"PromptPilot mahalliy ishlab chiqish sozlamalarida ishga tushirilgan.","body":"## Muammo\n\nKo‘rsatmalar, sozlamalar va avvalgi natijalar turli joylarda qolib ketsa, promptlar bilan ishlashni boshqarish qiyinlashadi.\n\n## Yaratgan yechimim\n\nPrompt vositalari, akkaunt sozlamalari va tarixni bitta jarayonga birlashtiruvchi Next.js ilovasini yaratdim. Supabase autentifikatsiya va ma’lumotlarni saqlashga xizmat qiladi; AI qismi sinov provayderi yoki OpenAI bilan ishlaydi.\n\n## Bajargan ishlarim\n\n- Ilovani boshidan oxirigacha loyihaladim va yaratdim.\n\n- Interfeys, prompt va dasturchi uchun ish jarayonlarini bajardim.\n\n- Autentifikatsiya, sozlamalar va tarixni Supabase bilan bog‘ladim.\n\n- Provayder tanlash, muqobil rejim va server so‘rovlarining tekshiruvlarini yaratdim.\n\n## Texnik qarorlar\n\n### AI provayderini almashtirish imkoniyati\n\nProvayder tanlash qismi ish jarayonini javob yaratuvchi servisdan ajratadi. Sinov rejimi haqiqiy API ulanmaganida ham ishlab chiqishga yordam beradi.\n\n### Tarixni saqlash — foydalanuvchi tanlovi\n\nAkkaunt sozlamalari tarixni saqlashni boshqaradi, ma’lumotlarga egalik esa Supabase satr darajasidagi xavfsizlik qoidalari orqali belgilanadi.\n\n## O‘rganganlarim\n\nInterfeysni autentifikatsiya, ma’lumotlar va tashqi AI servisi bilan bog‘lashda xato holatlari hamda akkauntlar chegarasini butun ilova bo‘ylab hisobga olish kerakligini o‘rgandim.\n\n## Keyingi qadamlar\n\n- Yopiq beta ro‘yxatini yakunlash va sozlangan muhitda asosiy jarayonlarni tekshirish.\n\n- Akkauntlar ajratilishi, provayderning muqobil rejimi va oldingi versiyaga qaytishni tekshirish.\n\n- Ilovani chiqarishdan oldin foydalanuvchi fikrlarini yig‘ish.","order":0}'::jsonb, '{"title":"PromptPilot","summary":"Promptlar bilan ishlashni tartibga soluvchi ilova: akkaunt sozlamalari, saqlangan tarix va almashtiriladigan AI provayder.","category":"Full-stack · AI vositasi","role":"Interfeysdan backendgacha mustaqil yaratdim","status":"Prototip · Beta sinoviga tayyorgarlik","stack":["Next.js","TypeScript","Supabase","OpenAI"],"repository":"https://github.com/sardorcodev/PromptPilot","image":"/images/projects/promptpilot.webp","imageAlt":"PromptPilot mahalliy ishlab chiqish sozlamalarida ishga tushirilgan.","body":"## Muammo\n\nKo‘rsatmalar, sozlamalar va avvalgi natijalar turli joylarda qolib ketsa, promptlar bilan ishlashni boshqarish qiyinlashadi.\n\n## Yaratgan yechimim\n\nPrompt vositalari, akkaunt sozlamalari va tarixni bitta jarayonga birlashtiruvchi Next.js ilovasini yaratdim. Supabase autentifikatsiya va ma’lumotlarni saqlashga xizmat qiladi; AI qismi sinov provayderi yoki OpenAI bilan ishlaydi.\n\n## Bajargan ishlarim\n\n- Ilovani boshidan oxirigacha loyihaladim va yaratdim.\n\n- Interfeys, prompt va dasturchi uchun ish jarayonlarini bajardim.\n\n- Autentifikatsiya, sozlamalar va tarixni Supabase bilan bog‘ladim.\n\n- Provayder tanlash, muqobil rejim va server so‘rovlarining tekshiruvlarini yaratdim.\n\n## Texnik qarorlar\n\n### AI provayderini almashtirish imkoniyati\n\nProvayder tanlash qismi ish jarayonini javob yaratuvchi servisdan ajratadi. Sinov rejimi haqiqiy API ulanmaganida ham ishlab chiqishga yordam beradi.\n\n### Tarixni saqlash — foydalanuvchi tanlovi\n\nAkkaunt sozlamalari tarixni saqlashni boshqaradi, ma’lumotlarga egalik esa Supabase satr darajasidagi xavfsizlik qoidalari orqali belgilanadi.\n\n## O‘rganganlarim\n\nInterfeysni autentifikatsiya, ma’lumotlar va tashqi AI servisi bilan bog‘lashda xato holatlari hamda akkauntlar chegarasini butun ilova bo‘ylab hisobga olish kerakligini o‘rgandim.\n\n## Keyingi qadamlar\n\n- Yopiq beta ro‘yxatini yakunlash va sozlangan muhitda asosiy jarayonlarni tekshirish.\n\n- Akkauntlar ajratilishi, provayderning muqobil rejimi va oldingi versiyaga qaytishni tekshirish.\n\n- Ilovani chiqarishdan oldin foydalanuvchi fikrlarini yig‘ish.","order":0}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'smart-agro-ai', 'uz', '{"title":"Smart Agro AI","summary":"React interfeysi, Python API va jamoaning ekin tavsiya modelini bog‘lovchi qishloq xo‘jaligi paneli.","category":"Full-stack · Jamoaviy MVP","role":"Frontend va backend; ML alohida yaratilgan","status":"MVP · Namoyish","stack":["React","FastAPI","Python","SQLite"],"repository":"https://github.com/sardorcodev/smart-agroAI","image":"/images/projects/smart-agro-ai.webp","imageAlt":"Smart Agro AI MVP interfeysi. Paneldagi ayrim bo‘limlar namoyish uchun yaratilgan.","body":"## Muammo\n\nQishloq xo‘jaligi uchun qaror qabul qilish prototipi kiritilgan ma’lumotlar, ob-havo va ekin tavsiyalarini bitta tushunarli jarayonda ko‘rsatishi kerak.\n\n## Yaratgan yechimim\n\nIlovaning MLdan tashqari qismlarini, jumladan React frontend va FastAPI backendni yaratdim. MVP shakllar, tahlil natijalari va ob-havo ma’lumotlarini bog‘laydi, ekin tavsiyalari esa jamoaning modelidan olinadi.\n\n## Bajargan ishlarim\n\n- Ilovaning frontend va backend qismlarini yaratdim.\n\n- Ma’lumot kiritish va tahlil natijalarini ko‘rsatish interfeysini bajardim.\n\n- Panelni qo‘llab-quvvatlaydigan API va ma’lumotlar oqimi ustida ishladim.\n\n- Hackathon davomida GREEN OPS jamoasiga hissa qo‘shdim.\n\n## Texnik qarorlar\n\n### Tavsiyani ma’lumotlar bilan birga ko‘rsatish\n\nPanel kiritilgan ma’lumotlar va ob-havoni natija bilan bog‘laydi. Bu foydalanuvchiga butun jarayonni tushunishga yordam beradi.\n\n### Namoyish rejimini aniq belgilash\n\nBackend model ishlashi va simulyatsiya rejimini ajratadi. Ilova hozir MVP; model tekshiruvi va dataset manbasi bo‘yicha cheklovlar mavjud.\n\n## O‘rganganlarim\n\nJamoaning ML qismi atrofida ilova yaratish model, API va natijani ko‘rsatuvchi interfeys o‘rtasidagi chegaralarni yaxshiroq tushunishimga yordam berdi.\n\n## Keyingi qadamlar\n\n- Tahlil jarayoni va uning xato holatlarini yaxshilash.\n\n- Interfeys va backendni mustahkamlashda davom etish.\n\n- Amaliy qo‘llashdan oldin ML ustida ishlagan jamoa a’zosi bilan dataset manbasi va model tekshiruvini hal qilish.","order":1}'::jsonb, '{"title":"Smart Agro AI","summary":"React interfeysi, Python API va jamoaning ekin tavsiya modelini bog‘lovchi qishloq xo‘jaligi paneli.","category":"Full-stack · Jamoaviy MVP","role":"Frontend va backend; ML alohida yaratilgan","status":"MVP · Namoyish","stack":["React","FastAPI","Python","SQLite"],"repository":"https://github.com/sardorcodev/smart-agroAI","image":"/images/projects/smart-agro-ai.webp","imageAlt":"Smart Agro AI MVP interfeysi. Paneldagi ayrim bo‘limlar namoyish uchun yaratilgan.","body":"## Muammo\n\nQishloq xo‘jaligi uchun qaror qabul qilish prototipi kiritilgan ma’lumotlar, ob-havo va ekin tavsiyalarini bitta tushunarli jarayonda ko‘rsatishi kerak.\n\n## Yaratgan yechimim\n\nIlovaning MLdan tashqari qismlarini, jumladan React frontend va FastAPI backendni yaratdim. MVP shakllar, tahlil natijalari va ob-havo ma’lumotlarini bog‘laydi, ekin tavsiyalari esa jamoaning modelidan olinadi.\n\n## Bajargan ishlarim\n\n- Ilovaning frontend va backend qismlarini yaratdim.\n\n- Ma’lumot kiritish va tahlil natijalarini ko‘rsatish interfeysini bajardim.\n\n- Panelni qo‘llab-quvvatlaydigan API va ma’lumotlar oqimi ustida ishladim.\n\n- Hackathon davomida GREEN OPS jamoasiga hissa qo‘shdim.\n\n## Texnik qarorlar\n\n### Tavsiyani ma’lumotlar bilan birga ko‘rsatish\n\nPanel kiritilgan ma’lumotlar va ob-havoni natija bilan bog‘laydi. Bu foydalanuvchiga butun jarayonni tushunishga yordam beradi.\n\n### Namoyish rejimini aniq belgilash\n\nBackend model ishlashi va simulyatsiya rejimini ajratadi. Ilova hozir MVP; model tekshiruvi va dataset manbasi bo‘yicha cheklovlar mavjud.\n\n## O‘rganganlarim\n\nJamoaning ML qismi atrofida ilova yaratish model, API va natijani ko‘rsatuvchi interfeys o‘rtasidagi chegaralarni yaxshiroq tushunishimga yordam berdi.\n\n## Keyingi qadamlar\n\n- Tahlil jarayoni va uning xato holatlarini yaxshilash.\n\n- Interfeys va backendni mustahkamlashda davom etish.\n\n- Amaliy qo‘llashdan oldin ML ustida ishlagan jamoa a’zosi bilan dataset manbasi va model tekshiruvini hal qilish.","order":1}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'propaint', 'uz', '{"title":"ProPaint","summary":"Canvas vositalari, ortga va oldinga qaytarish, rang boshqaruvi va PNG eksportiga ega brauzer rasm muharriri.","category":"Frontend · Ijodiy vosita","role":"Boshidan oxirigacha mustaqil yaratdim","status":"Prototip · Barqarorlashtirish","stack":["React","JavaScript","Canvas","Redux Toolkit"],"repository":"https://github.com/sardorcodev/paint-web","image":"/images/projects/propaint.webp","imageAlt":"ProPaint mahalliy muhitda: Canvas muharriri va chizish boshqaruvlari.","body":"## Muammo\n\nRasm muharririda foydalanuvchi harakatlarni tez almashtirganda vositalar, Canvas holati va tarix bir-biriga mos qolishi kerak.\n\n## Yaratgan yechimim\n\nMaxsus Canvas muharriri asosida React ilovasini yaratdim. Hozirgi prototip chizish, sodda shakllar, rang tanlash, ortga va oldinga qaytarish hamda PNG eksportini qo‘llaydi.\n\n## Bajargan ishlarim\n\n- Ilovani mustaqil yaratdim.\n\n- Maxsus Canvas muharriri va chizish vositalarini bajardim.\n\n- Muharrir boshqaruvi va holatini React hamda Redux Toolkit bilan bog‘ladim.\n\n- Harakatlar tarixi va rasm eksportini yaratdim.\n\n## Texnik qarorlar\n\n### Muharrir vazifalarini ajratish\n\nMuharrirda controller, renderer, history va tool modullari bor. Bu barcha mantiqni bitta React komponentiga joylamasdan, chizish imkoniyatlarini rivojlantirishga yordam beradi.\n\n### Avval asosiy harakatlarni barqarorlashtirish\n\nHozir chizish va tarix bilan ishlash ustuvor. Loyihani saqlash/yuklash, qatlamlar interfeysi va masshtab hamda siljitish keyingi ishlar qatorida.\n\n## O‘rganganlarim\n\nCanvas bilan ishlashda tasvirlash, foydalanuvchi harakatlari va holat boshqaruvi birlashadi. Ortga va oldinga qaytarish uchun har bir muharrir harakatini aniq belgilash zarur.\n\n## Keyingi qadamlar\n\n- Muharrirni barqarorlashtirish va tarix xatti-harakatini tekshirish.\n\n- Hujjatlarni yaxshilash va test tuzilmasiga moslashtirish.\n\n- Poydevor tayyor bo‘lgach, saqlash/yuklash va Canvas navigatsiyasini rivojlantirish.","order":2}'::jsonb, '{"title":"ProPaint","summary":"Canvas vositalari, ortga va oldinga qaytarish, rang boshqaruvi va PNG eksportiga ega brauzer rasm muharriri.","category":"Frontend · Ijodiy vosita","role":"Boshidan oxirigacha mustaqil yaratdim","status":"Prototip · Barqarorlashtirish","stack":["React","JavaScript","Canvas","Redux Toolkit"],"repository":"https://github.com/sardorcodev/paint-web","image":"/images/projects/propaint.webp","imageAlt":"ProPaint mahalliy muhitda: Canvas muharriri va chizish boshqaruvlari.","body":"## Muammo\n\nRasm muharririda foydalanuvchi harakatlarni tez almashtirganda vositalar, Canvas holati va tarix bir-biriga mos qolishi kerak.\n\n## Yaratgan yechimim\n\nMaxsus Canvas muharriri asosida React ilovasini yaratdim. Hozirgi prototip chizish, sodda shakllar, rang tanlash, ortga va oldinga qaytarish hamda PNG eksportini qo‘llaydi.\n\n## Bajargan ishlarim\n\n- Ilovani mustaqil yaratdim.\n\n- Maxsus Canvas muharriri va chizish vositalarini bajardim.\n\n- Muharrir boshqaruvi va holatini React hamda Redux Toolkit bilan bog‘ladim.\n\n- Harakatlar tarixi va rasm eksportini yaratdim.\n\n## Texnik qarorlar\n\n### Muharrir vazifalarini ajratish\n\nMuharrirda controller, renderer, history va tool modullari bor. Bu barcha mantiqni bitta React komponentiga joylamasdan, chizish imkoniyatlarini rivojlantirishga yordam beradi.\n\n### Avval asosiy harakatlarni barqarorlashtirish\n\nHozir chizish va tarix bilan ishlash ustuvor. Loyihani saqlash/yuklash, qatlamlar interfeysi va masshtab hamda siljitish keyingi ishlar qatorida.\n\n## O‘rganganlarim\n\nCanvas bilan ishlashda tasvirlash, foydalanuvchi harakatlari va holat boshqaruvi birlashadi. Ortga va oldinga qaytarish uchun har bir muharrir harakatini aniq belgilash zarur.\n\n## Keyingi qadamlar\n\n- Muharrirni barqarorlashtirish va tarix xatti-harakatini tekshirish.\n\n- Hujjatlarni yaxshilash va test tuzilmasiga moslashtirish.\n\n- Poydevor tayyor bo‘lgach, saqlash/yuklash va Canvas navigatsiyasini rivojlantirish.","order":2}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
