insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'promptpilot', 'ru', '{"title":"PromptPilot","summary":"Упорядоченная работа с промптами: настройки аккаунта, история и сменяемый провайдер ИИ.","category":"Фулстек · Инструмент ИИ","role":"Создал самостоятельно: от интерфейса до бэкенда","status":"Прототип · Подготовка к бета-тесту","stack":["Next.js","TypeScript","Supabase","OpenAI"],"repository":"https://github.com/sardorcodev/PromptPilot","image":"/images/projects/promptpilot.webp","imageAlt":"PromptPilot запущен локально с настройками для разработки.","body":"## Задача\n\nКогда инструкции, настройки и предыдущие результаты разбросаны по разным местам, управлять работой с промптами становится сложнее.\n\n## Моё решение\n\nЯ создал приложение Next.js, которое объединяет инструменты для промптов, настройки аккаунта и историю. Supabase отвечает за аутентификацию и хранение данных, а слой ИИ может использовать тестовый провайдер или OpenAI.\n\n## Мой вклад\n\n- Спроектировал и реализовал приложение целиком.\n\n- Создал интерфейс и сценарии работы с промптами и задачами разработчика.\n\n- Подключил аутентификацию, настройки и историю к Supabase.\n\n- Реализовал выбор провайдера, резервный режим и серверные проверки запросов.\n\n## Технические решения\n\n### Сменяемый провайдер ИИ\n\nФабрика провайдеров отделяет рабочий процесс от сервиса генерации ответа. Тестовый режим позволяет разрабатывать без подключения к реальному API.\n\n### Сохранение истории по выбору пользователя\n\nНастройки аккаунта управляют сохранением истории, а политики безопасности на уровне строк определяют принадлежность данных.\n\n## Чему я научился\n\nСвязывая интерфейс с аутентификацией, данными и внешним сервисом ИИ, нужно учитывать ошибки и границы аккаунтов во всём приложении.\n\n## Следующие шаги\n\n- Завершить подготовку к закрытой бете и проверить основные сценарии в настроенном окружении.\n\n- Проверить изоляцию аккаунтов, резервный провайдер и откат релиза.\n\n- Собрать обратную связь перед выпуском продукта.","order":0}'::jsonb, '{"title":"PromptPilot","summary":"Упорядоченная работа с промптами: настройки аккаунта, история и сменяемый провайдер ИИ.","category":"Фулстек · Инструмент ИИ","role":"Создал самостоятельно: от интерфейса до бэкенда","status":"Прототип · Подготовка к бета-тесту","stack":["Next.js","TypeScript","Supabase","OpenAI"],"repository":"https://github.com/sardorcodev/PromptPilot","image":"/images/projects/promptpilot.webp","imageAlt":"PromptPilot запущен локально с настройками для разработки.","body":"## Задача\n\nКогда инструкции, настройки и предыдущие результаты разбросаны по разным местам, управлять работой с промптами становится сложнее.\n\n## Моё решение\n\nЯ создал приложение Next.js, которое объединяет инструменты для промптов, настройки аккаунта и историю. Supabase отвечает за аутентификацию и хранение данных, а слой ИИ может использовать тестовый провайдер или OpenAI.\n\n## Мой вклад\n\n- Спроектировал и реализовал приложение целиком.\n\n- Создал интерфейс и сценарии работы с промптами и задачами разработчика.\n\n- Подключил аутентификацию, настройки и историю к Supabase.\n\n- Реализовал выбор провайдера, резервный режим и серверные проверки запросов.\n\n## Технические решения\n\n### Сменяемый провайдер ИИ\n\nФабрика провайдеров отделяет рабочий процесс от сервиса генерации ответа. Тестовый режим позволяет разрабатывать без подключения к реальному API.\n\n### Сохранение истории по выбору пользователя\n\nНастройки аккаунта управляют сохранением истории, а политики безопасности на уровне строк определяют принадлежность данных.\n\n## Чему я научился\n\nСвязывая интерфейс с аутентификацией, данными и внешним сервисом ИИ, нужно учитывать ошибки и границы аккаунтов во всём приложении.\n\n## Следующие шаги\n\n- Завершить подготовку к закрытой бете и проверить основные сценарии в настроенном окружении.\n\n- Проверить изоляцию аккаунтов, резервный провайдер и откат релиза.\n\n- Собрать обратную связь перед выпуском продукта.","order":0}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'smart-agro-ai', 'ru', '{"title":"Smart Agro AI","summary":"Аграрная панель, связывающая интерфейс React, API на Python и командную модель рекомендаций культур.","category":"Фулстек · Командный MVP","role":"Фронтенд и бэкенд; ML создавался отдельно","status":"MVP · Демонстрация","stack":["React","FastAPI","Python","SQLite"],"repository":"https://github.com/sardorcodev/smart-agroAI","image":"/images/projects/smart-agro-ai.webp","imageAlt":"Интерфейс MVP Smart Agro AI. Некоторые разделы панели демонстрационные.","body":"## Задача\n\nПрототип поддержки аграрных решений должен объединять входные данные, погоду и рекомендации культур в понятный процесс.\n\n## Моё решение\n\nЯ создал части приложения вне ML, включая фронтенд на React и бэкенд на FastAPI. MVP связывает формы, результаты анализа и погоду, а рекомендации культур поступают от модели команды.\n\n## Мой вклад\n\n- Создал фронтенд и бэкенд приложения.\n\n- Реализовал интерфейс ввода данных и просмотра результатов анализа.\n\n- Работал над API и потоком данных для панели.\n\n- Внёс вклад в работу GREEN OPS на хакатоне.\n\n## Технические решения\n\n### Показать рекомендацию в контексте\n\nПанель связывает исходные данные и погоду с результатом, чтобы пользователь понимал весь процесс.\n\n### Ясно обозначить демонстрационный режим\n\nБэкенд различает работу модели и резервную симуляцию. Приложение остаётся MVP с ограниченной валидацией модели и неуточнённым происхождением датасета.\n\n## Чему я научился\n\nРабота над приложением вокруг командного ML-компонента помогла лучше понять границы между моделью, API и интерфейсом результатов.\n\n## Следующие шаги\n\n- Улучшить процесс анализа и обработку ошибок.\n\n- Продолжить развитие интерфейса и бэкенда.\n\n- Совместно с автором ML-части уточнить происхождение датасета и валидацию перед практическим применением.","order":1}'::jsonb, '{"title":"Smart Agro AI","summary":"Аграрная панель, связывающая интерфейс React, API на Python и командную модель рекомендаций культур.","category":"Фулстек · Командный MVP","role":"Фронтенд и бэкенд; ML создавался отдельно","status":"MVP · Демонстрация","stack":["React","FastAPI","Python","SQLite"],"repository":"https://github.com/sardorcodev/smart-agroAI","image":"/images/projects/smart-agro-ai.webp","imageAlt":"Интерфейс MVP Smart Agro AI. Некоторые разделы панели демонстрационные.","body":"## Задача\n\nПрототип поддержки аграрных решений должен объединять входные данные, погоду и рекомендации культур в понятный процесс.\n\n## Моё решение\n\nЯ создал части приложения вне ML, включая фронтенд на React и бэкенд на FastAPI. MVP связывает формы, результаты анализа и погоду, а рекомендации культур поступают от модели команды.\n\n## Мой вклад\n\n- Создал фронтенд и бэкенд приложения.\n\n- Реализовал интерфейс ввода данных и просмотра результатов анализа.\n\n- Работал над API и потоком данных для панели.\n\n- Внёс вклад в работу GREEN OPS на хакатоне.\n\n## Технические решения\n\n### Показать рекомендацию в контексте\n\nПанель связывает исходные данные и погоду с результатом, чтобы пользователь понимал весь процесс.\n\n### Ясно обозначить демонстрационный режим\n\nБэкенд различает работу модели и резервную симуляцию. Приложение остаётся MVP с ограниченной валидацией модели и неуточнённым происхождением датасета.\n\n## Чему я научился\n\nРабота над приложением вокруг командного ML-компонента помогла лучше понять границы между моделью, API и интерфейсом результатов.\n\n## Следующие шаги\n\n- Улучшить процесс анализа и обработку ошибок.\n\n- Продолжить развитие интерфейса и бэкенда.\n\n- Совместно с автором ML-части уточнить происхождение датасета и валидацию перед практическим применением.","order":1}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
insert into public.cms_entries(kind, slug, locale, draft, published, published_at, published_updated_at) values ('project', 'propaint', 'ru', '{"title":"ProPaint","summary":"Редактор рисования в браузере: Canvas, отмена и повтор действий, выбор цветов и экспорт PNG.","category":"Фронтенд · Инструмент для творчества","role":"Создал самостоятельно от начала до конца","status":"Прототип · Стабилизация","stack":["React","JavaScript","Canvas","Redux Toolkit"],"repository":"https://github.com/sardorcodev/paint-web","image":"/images/projects/propaint.webp","imageAlt":"ProPaint запущен локально: редактор Canvas и инструменты рисования.","body":"## Задача\n\nПри быстром переключении действий в редакторе инструменты, состояние холста и история должны оставаться согласованными.\n\n## Моё решение\n\nЯ создал приложение React вокруг собственного редактора Canvas. Прототип поддерживает рисование, простые фигуры, выбор цвета, отмену и повтор действий и экспорт PNG.\n\n## Мой вклад\n\n- Создал приложение самостоятельно.\n\n- Реализовал редактор Canvas и инструменты рисования.\n\n- Связал управление и состояние через React и Redux Toolkit.\n\n- Реализовал историю действий и экспорт изображения.\n\n## Технические решения\n\n### Разделить обязанности редактора\n\nКонтроллер, отрисовка, история и инструменты выделены в отдельные модули. Это позволяет развивать рисование без переноса всей логики в один компонент React.\n\n### Сначала стабилизировать основу\n\nСейчас в фокусе рисование и история. Сохранение проекта, интерфейс слоёв, масштабирование и перемещение остаются будущими задачами.\n\n## Чему я научился\n\nРабота с Canvas объединяет отрисовку, ввод и управление состоянием. Для отмены и повтора нужно чётко определить каждое действие редактора.\n\n## Следующие шаги\n\n- Стабилизировать редактор и проверить историю.\n\n- Улучшить документацию и согласовать её с тестами.\n\n- После укрепления основы изучить сохранение проектов и навигацию по холсту.","order":2}'::jsonb, '{"title":"ProPaint","summary":"Редактор рисования в браузере: Canvas, отмена и повтор действий, выбор цветов и экспорт PNG.","category":"Фронтенд · Инструмент для творчества","role":"Создал самостоятельно от начала до конца","status":"Прототип · Стабилизация","stack":["React","JavaScript","Canvas","Redux Toolkit"],"repository":"https://github.com/sardorcodev/paint-web","image":"/images/projects/propaint.webp","imageAlt":"ProPaint запущен локально: редактор Canvas и инструменты рисования.","body":"## Задача\n\nПри быстром переключении действий в редакторе инструменты, состояние холста и история должны оставаться согласованными.\n\n## Моё решение\n\nЯ создал приложение React вокруг собственного редактора Canvas. Прототип поддерживает рисование, простые фигуры, выбор цвета, отмену и повтор действий и экспорт PNG.\n\n## Мой вклад\n\n- Создал приложение самостоятельно.\n\n- Реализовал редактор Canvas и инструменты рисования.\n\n- Связал управление и состояние через React и Redux Toolkit.\n\n- Реализовал историю действий и экспорт изображения.\n\n## Технические решения\n\n### Разделить обязанности редактора\n\nКонтроллер, отрисовка, история и инструменты выделены в отдельные модули. Это позволяет развивать рисование без переноса всей логики в один компонент React.\n\n### Сначала стабилизировать основу\n\nСейчас в фокусе рисование и история. Сохранение проекта, интерфейс слоёв, масштабирование и перемещение остаются будущими задачами.\n\n## Чему я научился\n\nРабота с Canvas объединяет отрисовку, ввод и управление состоянием. Для отмены и повтора нужно чётко определить каждое действие редактора.\n\n## Следующие шаги\n\n- Стабилизировать редактор и проверить историю.\n\n- Улучшить документацию и согласовать её с тестами.\n\n- После укрепления основы изучить сохранение проектов и навигацию по холсту.","order":2}'::jsonb, '2026-10-04T10:50:30.000Z', '2026-10-04T10:50:30.000Z') on conflict (kind, slug, locale) do nothing;
