insert into public.cms_entries(kind, slug, locale, draft) values ('post', 'portfolio-yangi-bosqichda', 'uz', '{"title":"Portfolio yangi bosqichda","summary":"sardorcodev portfoliom uch tilda ishlaydi. Bu yerda loyihalarim, yutuqlarim va o‘rganayotganlarim haqida yozib boraman.","body":"Portfoliomning yangi versiyasi sardorcodev.uz manzilida ishga tushdi. Sayt o‘zbek, ingliz va rus tillarida ishlaydi.\n\n## Nimalar bor?\n\nAsosiy loyihalarim — ProPaint, PromptPilot va Smart Agro AI. ProPaint va PromptPilot’ni boshidan oxirigacha o‘zim yaratganman. Smart Agro AI jamoaviy loyiha: unda ML qismidan tashqari qismlarni bajarganman.\n\n## Bu blog haqida\n\nBu yerda qilayotgan ishlarim, yutuqlarim va o‘rganayotganlarimni yozib boraman. Hozir frontend va backend bilan ishlayman, ML asoslarini o‘rganyapman.\n\n---\n\n*Bu boshlang‘ich qoralama tasdiqlangan ma’lumotlar asosida tayyorlangan. Nashrdan oldin o‘z fikrlaringiz bilan tahrirlang va ushbu izohni olib tashlang.*","category":"work","image":"","imageAlt":""}'::jsonb) on conflict (kind, slug, locale) do nothing;
